26: // UnmarshalYAML supports both tool_names and toolNames in YAML.
27: func (d *DeclaredScope) UnmarshalYAML(value *yaml.Node) error {
28: 	type rawDeclaredScope struct {
29: 		Name         string               `yaml:"name"`
30: 		Kind         dossiers.DossierKind `yaml:"kind"`
31: 		Keywords     []string             `yaml:"keywords"`
