39: 		return err
40: 	}
41: 	d.Name = raw.Name
42: 	d.Kind = raw.Kind
43: 	d.Keywords = raw.Keywords
44: 	d.ToolNames = raw.ToolNames
45: 	if len(d.ToolNames) == 0 && len(raw.ToolNamesAlt) > 0 {
46: 		d.ToolNames = raw.ToolNamesAlt
