60: // LoadScopeConfig reads declared scopes from config.yaml under the `scopes:` key.
61: // If configPath does not exist, or the `scopes:` key is missing, it returns an empty config without error.
62: func LoadScopeConfig(configPath string) (*ScopeConfig, error) {
63: 	if configPath == "" {
64: 		return &ScopeConfig{}, nil
65: 	}
66: 
67: 	data, err := os.ReadFile(configPath)
68: 	if err != nil {
69: 		if os.IsNotExist(err) {
70: 			return &ScopeConfig{}, nil
71: 		}
72: 		return nil, fmt.Errorf("reading scope config %s: %w", configPath, err)
73: 	}
74: 
75: 	if len(strings.TrimSpace(string(data))) == 0 {
76: 		return &ScopeConfig{}, nil
77: 	}
78: 
79: 	var root struct {
80: 		Scopes *ScopeConfig `yaml:"scopes"`
81: 	}
82: 	if err := yaml.Unmarshal(data, &root); err != nil {
83: 		return nil, fmt.Errorf("parsing scope config %s: %w", configPath, err)
84: 	}
85: 
86: 	if root.Scopes == nil {
87: 		return &ScopeConfig{}, nil
88: 	}
89: 
90: 	cfg := root.Scopes
91: 	for i := range cfg.Topics {
92: 		if cfg.Topics[i].Kind == "" {
93: 			cfg.Topics[i].Kind = dossiers.DossierKindTopic
94: 		}
95: 	}
96: 	for i := range cfg.Externals {
97: 		if cfg.Externals[i].Kind == "" {
98: 			cfg.Externals[i].Kind = dossiers.DossierKindExternal
99: 		}
100: 	}
101: 	for i := range cfg.Procedures {
102: 		if cfg.Procedures[i].Kind == "" {
103: 			cfg.Procedures[i].Kind = dossiers.DossierKindProcedure
104: 		}
105: 	}
106: 
107: 	return cfg, nil
108: }
