110: // ModuleScope represents a derived module scope rolled up from file path anchors and symbols.
111: type ModuleScope struct {
112: 	Name      string               `json:"name" yaml:"name"`
113: 	Kind      dossiers.DossierKind `json:"kind,omitempty" yaml:"kind,omitempty"`
114: 	PathGlobs []string             `json:"path_globs,omitempty" yaml:"path_globs,omitempty"`
115: 	Symbols   []string             `json:"symbols,omitempty" yaml:"symbols,omitempty"`
116: }
117: 
118: type parsedAnchor struct {
119: 	filePath string
120: 	symbol   string
121: }
122: 
123: func parseAnchor(raw string) parsedAnchor {
124: 	trimmed := strings.TrimSpace(raw)
125: 	if trimmed == "" {
126: 		return parsedAnchor{}
127: 	}
128: 
129: 	if strings.HasPrefix(trimmed, "file:") {
130: 		trimmed = strings.TrimPrefix(trimmed, "file:")
131: 	}
132: 
133: 	if strings.HasPrefix(trimmed, "symbol:") {
134: 		return parsedAnchor{symbol: strings.TrimPrefix(trimmed, "symbol:")}
135: 	}
136: 
137: 	// Check if path#symbol
138: 	if strings.Contains(trimmed, "#") {
139: 		parts := strings.SplitN(trimmed, "#", 2)
140: 		return parsedAnchor{
141: 			filePath: strings.TrimSpace(parts[0]),
142: 			symbol:   strings.TrimSpace(parts[1]),
143: 		}
144: 	}
145: 
146: 	// Check if path:symbol (avoid drive letter like C:)
147: 	if idx := strings.Index(trimmed, ":"); idx > 1 {
148: 		p := strings.TrimSpace(trimmed[:idx])
149: 		s := strings.TrimSpace(trimmed[idx+1:])
150: 		if strings.Contains(p, "/") || strings.Contains(p, ".") {
151: 			return parsedAnchor{
152: 				filePath: p,
153: 				symbol:   s,
154: 			}
155: 		}
156: 	}
157: 
158: 	return parsedAnchor{filePath: trimmed}
159: }
160: 
161: func getAnchorDir(filePath string) string {
162: 	clean := filepath.ToSlash(filepath.Clean(filePath))
163: 	clean = strings.TrimPrefix(clean, "./")
164: 	clean = strings.TrimPrefix(clean, "/")
165: 
166: 	// If glob pattern ending in /** or /*
167: 	clean = strings.TrimSuffix(clean, "/**")
168: 	clean = strings.TrimSuffix(clean, "/*")
169: 
170: 	// If it has a file extension or is a file name
171: 	if filepath.Ext(clean) != "" {
172: 		dir := filepath.ToSlash(filepath.Dir(clean))
173: 		if dir == "." || dir == "/" {
174: 			return ""
175: 		}
176: 		return dir
177: 	}
178: 
179: 	if clean == "." || clean == "/" {
180: 		return ""
181: 	}
182: 	return clean
183: }
184: 
185: func getParentMeaningfulDir(dir string) string {
186: 	if dir == "" || dir == "." || dir == "/" {
187: 		return ""
188: 	}
189: 	parent := filepath.ToSlash(filepath.Dir(dir))
190: 	if parent == "." || parent == "/" {
191: 		parent = ""
192: 	}
193: 
194: 	// Do not roll up past top-level directory under internal/ or cmd/ or repo root
195: 	if strings.HasPrefix(dir, "internal/") {
196: 		if parent == "internal" || parent == "" {
197: 			return dir
198: 		}
199: 		return parent
200: 	}
201: 
202: 	if strings.HasPrefix(dir, "cmd/") {
203: 		if parent == "cmd" || parent == "" {
204: 			return dir
205: 		}
206: 		return parent
207: 	}
208: 
209: 	if parent == "" {
210: 		return dir
211: 	}
212: 	return parent
213: }
214: 
215: func deriveScopeName(dir string) string {
216: 	clean := filepath.ToSlash(filepath.Clean(dir))
217: 	clean = strings.TrimPrefix(clean, "./")
218: 	clean = strings.TrimPrefix(clean, "/")
219: 
220: 	var rel string
221: 	if strings.HasPrefix(clean, "internal/") {
222: 		rel = strings.TrimPrefix(clean, "internal/")
223: 	} else if strings.HasPrefix(clean, "cmd/") {
224: 		rel = clean
225: 	} else {
226: 		rel = clean
227: 	}
228: 
229: 	if rel == "" || rel == "." {
230: 		rel = "root"
231: 	}
232: 
233: 	parts := strings.Split(rel, "/")
234: 	for i, p := range parts {
235: 		parts[i] = strings.ReplaceAll(p, "_", "-")
236: 	}
237: 	return strings.Join(parts, "/")
238: }
