240: // DeriveModuleScopes derives module scopes by rolling up file path anchors to the nearest meaningful parent directory:
241: // - Strip the filename, take the directory
242: // - If a directory has <= 2 files, roll up to the parent
243: // - Use the path relative to internal/ or cmd/ or the repo root as the scope name
244: // - Convert path separators to / and prefix with the top-level dir (e.g. core/transcript-parser)
245: // Returns deduplicated, sorted module scopes.
246: func DeriveModuleScopes(anchors []string) []ModuleScope {
247: 	if len(anchors) == 0 {
248: 		return nil
249: 	}
250: 
251: 	var parsedList []parsedAnchor
252: 	filesInDir := make(map[string]map[string]bool)
253: 
254: 	for _, a := range anchors {
255: 		p := parseAnchor(a)
256: 		if p.filePath == "" && p.symbol == "" {
257: 			continue
258: 		}
259: 		parsedList = append(parsedList, p)
260: 
261: 		if p.filePath != "" {
262: 			d := getAnchorDir(p.filePath)
263: 			if filesInDir[d] == nil {
264: 				filesInDir[d] = make(map[string]bool)
265: 			}
266: 			filesInDir[d][p.filePath] = true
267: 		}
268: 	}
269: 
270: 	if len(parsedList) == 0 {
271: 		return nil
272: 	}
273: 
274: 	type modAccum struct {
275: 		name       string
276: 		pathGlobs  map[string]bool
277: 		symbols    map[string]bool
278: 	}
279: 	accumMap := make(map[string]*modAccum)
280: 
281: 	for _, p := range parsedList {
282: 		var targetDir string
283: 		if p.filePath != "" {
284: 			rawDir := getAnchorDir(p.filePath)
285: 			fileCount := len(filesInDir[rawDir])
286: 			if fileCount <= 2 {
287: 				targetDir = getParentMeaningfulDir(rawDir)
288: 			} else {
289: 				targetDir = rawDir
290: 			}
291: 		}
292: 
293: 		scopeName := deriveScopeName(targetDir)
294: 		acc, ok := accumMap[scopeName]
295: 		if !ok {
296: 			acc = &modAccum{
297: 				name:      scopeName,
298: 				pathGlobs: make(map[string]bool),
299: 				symbols:   make(map[string]bool),
300: 			}
301: 			accumMap[scopeName] = acc
302: 		}
303: 
304: 		if p.filePath != "" {
305: 			cleanPath := filepath.ToSlash(filepath.Clean(p.filePath))
306: 			cleanPath = strings.TrimPrefix(cleanPath, "./")
307: 			cleanPath = strings.TrimPrefix(cleanPath, "/")
308: 			acc.pathGlobs[cleanPath] = true
309: 		}
310: 		if p.symbol != "" {
311: 			acc.symbols[p.symbol] = true
312: 		}
313: 	}
314: 
315: 	result := make([]ModuleScope, 0, len(accumMap))
316: 	for _, acc := range accumMap {
317: 		globs := make([]string, 0, len(acc.pathGlobs))
318: 		for g := range acc.pathGlobs {
319: 			globs = append(globs, g)
320: 		}
321: 		sort.Strings(globs)
322: 
323: 		syms := make([]string, 0, len(acc.symbols))
324: 		for s := range acc.symbols {
325: 			syms = append(syms, s)
326: 		}
327: 		sort.Strings(syms)
328: 
329: 		result = append(result, ModuleScope{
330: 			Name:      acc.name,
331: 			Kind:      dossiers.DossierKindModule,
332: 			PathGlobs: globs,
333: 			Symbols:   syms,
334: 		})
335: 	}
336: 
337: 	sort.Slice(result, func(i, j int) bool {
338: 		return result[i].Name < result[j].Name
339: 	})
340: 
341: 	return result
342: }
