344: // AliasMap maps old scope names to new ones (from split ops).
345: type AliasMap struct {
346: 	aliases map[string]string
347: 	targets map[string][]string
348: }
349: 
350: // NewAliasMap creates an empty AliasMap.
351: func NewAliasMap() *AliasMap {
352: 	return &AliasMap{
353: 		aliases: make(map[string]string),
354: 		targets: make(map[string][]string),
355: 	}
356: }
357: 
358: // Add registers an old scope mapping to its replacement dossiers.
359: func (a *AliasMap) Add(oldScope string, newDossiers []string) {
360: 	if a == nil {
361: 		return
362: 	}
363: 	if a.aliases == nil {
364: 		a.aliases = make(map[string]string)
365: 	}
366: 	if a.targets == nil {
367: 		a.targets = make(map[string][]string)
368: 	}
369: 
370: 	oldScope = strings.TrimSpace(oldScope)
371: 	if oldScope == "" || len(newDossiers) == 0 {
372: 		return
373: 	}
374: 
375: 	a.targets[oldScope] = append(a.targets[oldScope], newDossiers...)
376: 	if _, exists := a.aliases[oldScope]; !exists {
377: 		a.aliases[oldScope] = strings.TrimSpace(newDossiers[0])
378: 	}
379: }
380: 
381: // SetAlias sets a direct single oldScope -> newScope alias.
382: func (a *AliasMap) SetAlias(oldScope, newScope string) {
383: 	if a == nil {
384: 		return
385: 	}
386: 	if a.aliases == nil {
387: 		a.aliases = make(map[string]string)
388: 	}
389: 	if a.targets == nil {
390: 		a.targets = make(map[string][]string)
391: 	}
392: 	oldScope = strings.TrimSpace(oldScope)
393: 	newScope = strings.TrimSpace(newScope)
394: 	if oldScope == "" || newScope == "" {
395: 		return
396: 	}
397: 	a.aliases[oldScope] = newScope
398: 	a.targets[oldScope] = []string{newScope}
399: }
400: 
401: // HasAlias checks if the given scope has an alias.
402: func (a *AliasMap) HasAlias(scope string) bool {
403: 	if a == nil || a.aliases == nil {
404: 		return false
405: 	}
406: 	_, ok := a.aliases[strings.TrimSpace(scope)]
407: 	return ok
408: }
409: 
410: // Targets returns all replacement dossiers for an old scope.
411: func (a *AliasMap) Targets(scope string) []string {
412: 	if a == nil || a.targets == nil {
413: 		return nil
414: 	}
415: 	return a.targets[strings.TrimSpace(scope)]
416: }
417: 
418: // Resolve follows the alias chain to the current scope name.
419: // Prevents infinite loops (max depth 10 and cycle detection).
420: func (a *AliasMap) Resolve(scope string) string {
421: 	if a == nil || a.aliases == nil {
422: 		return scope
423: 	}
424: 	current := strings.TrimSpace(scope)
425: 	if current == "" {
426: 		return ""
427: 	}
428: 
429: 	maxDepth := 10
430: 	visited := make(map[string]bool)
431: 
432: 	for depth := 0; depth < maxDepth; depth++ {
433: 		next, exists := a.aliases[current]
434: 		if !exists || next == "" || next == current {
435: 			break
436: 		}
437: 		if visited[next] {
438: 			break
439: 		}
440: 		visited[current] = true
441: 		current = next
442: 	}
443: 	return current
444: }
445: 
446: // AllAliases returns all old and new scope names known to the alias map, sorted.
447: func (a *AliasMap) AllAliases() []string {
448: 	if a == nil {
449: 		return nil
450: 	}
451: 	seen := make(map[string]bool)
452: 	for k := range a.aliases {
453: 		if k != "" {
454: 			seen[k] = true
455: 		}
456: 	}
457: 	for _, tgts := range a.targets {
458: 		for _, t := range tgts {
459: 			if t != "" {
460: 				seen[t] = true
461: 			}
462: 		}
463: 	}
464: 
465: 	res := make([]string, 0, len(seen))
466: 	for s := range seen {
467: 		res = append(res, s)
468: 	}
469: 	sort.Strings(res)
470: 	return res
471: }
472: 
473: // BuildAliasMap iterates all ops from the reader, collecting split ops to build the AliasMap.
474: func BuildAliasMap(opsReader *ops.Reader, ctx context.Context) (*AliasMap, error) {
475: 	aliasMap := NewAliasMap()
476: 	if opsReader == nil {
477: 		return aliasMap, nil
478: 	}
479: 	if ctx == nil {
480: 		ctx = context.Background()
481: 	}
482: 
483: 	for batch, err := range opsReader.Iterate(ctx) {
484: 		if err != nil {
485: 			return nil, fmt.Errorf("reading ops for alias map: %w", err)
486: 		}
487: 		if batch == nil {
488: 			continue
489: 		}
490: 		for _, op := range batch.Ops {
491: 			if op.Type == ops.OpSplit {
492: 				oldScope := strings.TrimSpace(op.DossierScope)
493: 				var newDossiers []string
494: 				if raw, ok := op.Fields["new_dossiers"].([]string); ok {
495: 					for _, s := range raw {
496: 						if trimmed := strings.TrimSpace(s); trimmed != "" {
497: 							newDossiers = append(newDossiers, trimmed)
498: 						}
499: 					}
500: 				} else if raw, ok := op.Fields["new_dossiers"].([]any); ok {
501: 					for _, item := range raw {
502: 						if s, ok := item.(string); ok {
503: 							if trimmed := strings.TrimSpace(s); trimmed != "" {
504: 								newDossiers = append(newDossiers, trimmed)
505: 							}
506: 						}
507: 					}
508: 				}
509: 				if oldScope != "" && len(newDossiers) > 0 {
510: 					aliasMap.Add(oldScope, newDossiers)
511: 				}
512: 			}
513: 		}
514: 	}
515: 
516: 	return aliasMap, nil
517: }
