519: // ScopeResolver combines declared scopes, derived module scopes, and aliases.
520: type ScopeResolver struct {
521: 	config  *ScopeConfig
522: 	modules []ModuleScope
523: 	aliases *AliasMap
524: }
525: 
526: // NewScopeResolver creates a ScopeResolver.
527: func NewScopeResolver(config *ScopeConfig, modules []ModuleScope, aliases *AliasMap) *ScopeResolver {
528: 	if config == nil {
529: 		config = &ScopeConfig{}
530: 	}
531: 	if aliases == nil {
532: 		aliases = NewAliasMap()
533: 	}
534: 	return &ScopeResolver{
535: 		config:  config,
536: 		modules: modules,
537: 		aliases: aliases,
538: 	}
539: }
