541: // ResolveScope resolves anchors and keywords to the best matching scope name:
542: // 1. First check aliases
543: // 2. Then try to match anchors against module scopes (path prefix match)
544: // 3. Then try to match keywords against declared topics, externals, procedures
545: // Returns the best matching scope name, or empty string if no match.
546: func (r *ScopeResolver) ResolveScope(anchors []string, keywords []string) string {
547: 	if r == nil {
548: 		return ""
549: 	}
550: 
551: 	// 1. First check aliases
552: 	if r.aliases != nil {
553: 		for _, a := range anchors {
554: 			trimmed := strings.TrimSpace(a)
555: 			if trimmed != "" && r.aliases.HasAlias(trimmed) {
556: 				return r.aliases.Resolve(trimmed)
557: 			}
558: 		}
559: 		for _, kw := range keywords {
560: 			trimmed := strings.TrimSpace(kw)
561: 			if trimmed != "" && r.aliases.HasAlias(trimmed) {
562: 				return r.aliases.Resolve(trimmed)
563: 			}
564: 		}
565: 	}
566: 
567: 	// 2. Then try to match anchors against module scopes (path prefix match)
568: 	if len(anchors) > 0 && len(r.modules) > 0 {
569: 		var bestMod *ModuleScope
570: 		bestScore := 0
571: 
572: 		for _, a := range anchors {
573: 			cleanA := filepath.ToSlash(filepath.Clean(strings.TrimSpace(a)))
574: 			cleanA = strings.TrimPrefix(cleanA, "file:")
575: 			cleanA = strings.TrimPrefix(cleanA, "./")
576: 			cleanA = strings.TrimPrefix(cleanA, "/")
577: 			if cleanA == "" || cleanA == "." {
578: 				continue
579: 			}
580: 
581: 			relA := cleanA
582: 			if strings.HasPrefix(relA, "internal/") {
583: 				relA = strings.TrimPrefix(relA, "internal/")
584: 			}
585: 			slugA := strings.ReplaceAll(relA, "_", "-")
586: 
587: 			for i := range r.modules {
588: 				mod := &r.modules[i]
589: 				score := 0
590: 
591: 				// Check exact or prefix match against mod.Name
592: 				if mod.Name != "" {
593: 					if mod.Name == slugA || mod.Name == relA {
594: 						score = 100
595: 					} else if strings.HasPrefix(slugA, mod.Name+"/") || strings.HasPrefix(relA, mod.Name+"/") {
596: 						score = 50 + len(mod.Name)*2
597: 					}
598: 				}
599: 
600: 				// Check against PathGlobs
601: 				for _, glob := range mod.PathGlobs {
602: 					cleanG := filepath.ToSlash(filepath.Clean(strings.TrimSpace(glob)))
603: 					cleanG = strings.TrimPrefix(cleanG, "./")
604: 					cleanG = strings.TrimPrefix(cleanG, "/")
605: 
606: 					if cleanA == cleanG {
607: 						if score < 90 {
608: 							score = 90
609: 						}
610: 					} else if strings.HasPrefix(cleanA, cleanG+"/") || strings.HasPrefix(cleanA, filepath.Dir(cleanG)+"/") {
611: 						cand := 40 + len(cleanG)
612: 						if cand > score {
613: 							score = cand
614: 						}
615: 					}
616: 				}
617: 
618: 				// Check against Symbols
619: 				for _, sym := range mod.Symbols {
620: 					if strings.Contains(a, sym) {
621: 						if score < 80 {
622: 							score = 80
623: 						}
624: 					}
625: 				}
626: 
627: 				if score > bestScore {
628: 					bestScore = score
629: 					bestMod = mod
630: 				}
631: 			}
632: 		}
633: 
634: 		if bestMod != nil && bestScore > 0 {
635: 			resolved := bestMod.Name
636: 			if r.aliases != nil {
637: 				resolved = r.aliases.Resolve(resolved)
638: 			}
639: 			return resolved
640: 		}
641: 	}
642: 
643: 	// 3. Then try to match keywords against declared topics, externals, procedures
644: 	if len(keywords) > 0 && r.config != nil {
645: 		allDeclared := make([]DeclaredScope, 0, len(r.config.Topics)+len(r.config.Externals)+len(r.config.Procedures))
