// Package delivery implements the v2 delivery engine: the injection ledger,
// ranking engine, budget enforcement, anchor verification, and exposure tracking.
// It is harness-agnostic; hook handlers in internal/harness/ call this engine.
package delivery

package delivery

// Channel represents an injection channel.
type Channel string

const (
	// ChannelSystem injects persistent knowledge via systemMessage.
	ChannelSystem Channel = "system"
	// ChannelEphemeral injects single-invocation context via ephemeralMessage.
	ChannelEphemeral Channel = "ephemeral"
	// ChannelDeny triggers a PreToolUse deny-once gate.
	ChannelDeny Channel = "deny"
	// ChannelPull represents entries fetched on demand via MCP tools.
	ChannelPull Channel = "pull"
)

// Moment represents an injection trigger moment.
type Moment string

const (
	// MomentTaskStart is the first invocation brief (≤500 tokens).
	MomentTaskStart Moment = "task_start"
	// MomentFirstEntry is the first entry into a dossier scope (≤150 tokens).
	MomentFirstEntry Moment = "first_entry"
	// MomentFirstTouch is the first touch of a file/symbol anchor (≤150 tokens).
	MomentFirstTouch Moment = "first_touch"
	// MomentAboutToEdit is a pointer before edit (≤50 tokens ephemeral).
	MomentAboutToEdit Moment = "about_to_edit"
	// MomentError is an error pattern match (≤200 tokens ephemeral).
	MomentError Moment = "error"
	// MomentGate is a deny-once for gated entries (≤200 tokens deny).
	MomentGate Moment = "gate"
)

// Budget defines token budgets per injection moment.
type Budget map[Moment]int

// DefaultBudgets returns the default token budgets per moment according to SPEC v2 §8.2.
func DefaultBudgets() map[Moment]int {
	return map[Moment]int{
		MomentTaskStart:   500,
		MomentFirstEntry:  150,
		MomentFirstTouch:  150,
		MomentAboutToEdit: 50,
		MomentError:       200,
		MomentGate:        200,
	}
}

package delivery

import (
	"fmt"
	"sync"
	"time"
)

// InjectionRecord records a single context injection into the agent context.
type InjectionRecord struct {
	EntryID     string    // e.g., "inv-01JXXXXXX"
	Channel     Channel
	Moment      Moment
	StepIndex   int       // transcript step where injected
	ContentHash string    // SHA-256 of the injected text
	Tag         string    // "[repo-memory <id>]" marker
	Timestamp   time.Time
}

// ExposureRecord records an entry that was exposed to the model via push or pull.
type ExposureRecord struct {
	EntryID   string
	Channel   Channel    // or "pull" for MCP pulls
	Moment    Moment     // empty for pulls
	Timestamp time.Time
}

// Ledger tracks injection and exposure history for a conversation.
type Ledger struct {
	mu                sync.RWMutex
	ConversationID    string
	Injections        []InjectionRecord
	SeenDossiers      map[string]bool  // scope → already pushed first-entry
	SeenAnchors       map[string]bool  // anchor → already pushed first-touch
	AcknowledgedGates map[string]bool  // entryID → gate acknowledged
	ExposureList      []ExposureRecord // entries pushed or pulled
}

// NewLedger constructs a new Ledger for the given conversation ID.
func NewLedger(conversationID string) *Ledger {
	return &Ledger{
		ConversationID:    conversationID,
		Injections:        make([]InjectionRecord, 0),
		SeenDossiers:      make(map[string]bool),
		SeenAnchors:       make(map[string]bool),
		AcknowledgedGates: make(map[string]bool),
		ExposureList:      make([]ExposureRecord, 0),
	}
}

// RecordInjection appends an injection to the ledger and records exposure.
func (l *Ledger) RecordInjection(rec InjectionRecord) {
	l.mu.Lock()
	defer l.mu.Unlock()

	if rec.Timestamp.IsZero() {
		rec.Timestamp = time.Now().UTC()
	}
	if rec.Tag == "" && rec.EntryID != "" {
		rec.Tag = fmt.Sprintf("[repo-memory %s]", rec.EntryID)
	}

	l.Injections = append(l.Injections, rec)
	l.ExposureList = append(l.ExposureList, ExposureRecord{
		EntryID:   rec.EntryID,
		Channel:   rec.Channel,
		Moment:    rec.Moment,
		Timestamp: rec.Timestamp,
	})
}

// RecordPull records an entry pulled on demand via MCP tools.
func (l *Ledger) RecordPull(entryID string) {
	l.mu.Lock()
	defer l.mu.Unlock()

	l.ExposureList = append(l.ExposureList, ExposureRecord{
		EntryID:   entryID,
		Channel:   ChannelPull,
		Moment:    "",
		Timestamp: time.Now().UTC(),
	})
}

// HasSeenDossier reports whether a dossier scope has already been pushed in this conversation.
func (l *Ledger) HasSeenDossier(scope string) bool {
	l.mu.RLock()
	defer l.mu.RUnlock()
	return l.SeenDossiers[scope]
}

// MarkDossierSeen marks a dossier scope as having been pushed.
func (l *Ledger) MarkDossierSeen(scope string) {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.SeenDossiers[scope] = true
}

// HasSeenAnchor reports whether an anchor has already been pushed in this conversation.
func (l *Ledger) HasSeenAnchor(anchor string) bool {
	l.mu.RLock()
	defer l.mu.RUnlock()
	return l.SeenAnchors[anchor]
}

// MarkAnchorSeen marks an anchor as having been pushed.
func (l *Ledger) MarkAnchorSeen(anchor string) {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.SeenAnchors[anchor] = true
}

// IsGateAcknowledged reports whether a gate has already been acknowledged for an entry.
func (l *Ledger) IsGateAcknowledged(entryID string) bool {
	l.mu.RLock()
	defer l.mu.RUnlock()
	return l.AcknowledgedGates[entryID]
}

// AcknowledgeGate records that a gate has been acknowledged for an entry.
func (l *Ledger) AcknowledgeGate(entryID string) {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.AcknowledgedGates[entryID] = true
}

// RearmDedup clears SeenDossiers and SeenAnchors following compaction or rewind.
func (l *Ledger) RearmDedup() {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.SeenDossiers = make(map[string]bool)
	l.SeenAnchors = make(map[string]bool)
}

// GetExposureList returns a copy of all entries exposed in this conversation.
func (l *Ledger) GetExposureList() []ExposureRecord {
	l.mu.RLock()
	defer l.mu.RUnlock()
	results := make([]ExposureRecord, len(l.ExposureList))
	copy(results, l.ExposureList)
	return results
}

// FindInjectionAfterStep returns injections that occurred at or after the given step index.
func (l *Ledger) FindInjectionAfterStep(stepIndex int) []InjectionRecord {
	l.mu.RLock()
	defer l.mu.RUnlock()
	var results []InjectionRecord
	for _, inj := range l.Injections {
		if inj.StepIndex >= stepIndex {
			results = append(results, inj)
		}
	}
	if results == nil {
		results = []InjectionRecord{}
	}
	return results
}

package delivery

import (
	"os"
	"path/filepath"
	"strings"
)

// cleanAnchorFile extracts the file portion from an anchor string,
// stripping symbol qualifiers (':' or '#') and 'file:' prefixes.
func cleanAnchorFile(anchor string) string {
	trimmed := strings.TrimSpace(anchor)
	if trimmed == "" {
		return ""
	}

	// Remove "file:" prefix
	trimmed = strings.TrimPrefix(trimmed, "file:")

	// Pure symbols without file paths cannot be verified by file existence
	if strings.HasPrefix(trimmed, "symbol:") {
		return ""
	}

	// Check if path#symbol
	if strings.Contains(trimmed, "#") {
		parts := strings.SplitN(trimmed, "#", 2)
		trimmed = parts[0]
	}

	// Check if path:symbol (handle Windows drive letters like C:\)
	if len(trimmed) >= 2 && trimmed[1] == ':' && (trimmed[0] >= 'a' && trimmed[0] <= 'z' || trimmed[0] >= 'A' && trimmed[0] <= 'Z') {
		// Drive letter present, look for subsequent ':'
		if idx := strings.Index(trimmed[2:], ":"); idx >= 0 {
			trimmed = trimmed[:2+idx]
		}
	} else if idx := strings.Index(trimmed, ":"); idx >= 0 {
		trimmed = trimmed[:idx]
	}

	trimmed = strings.TrimSpace(trimmed)
	if trimmed == "" || trimmed == "." || trimmed == "/" {
		return ""
	}

	clean := filepath.ToSlash(filepath.Clean(trimmed))
	clean = strings.TrimPrefix(clean, "./")
	if clean == "." || clean == "/" || clean == "" {
		return ""
	}
	return clean
}

// VerifyAnchor checks whether an anchor's target file or directory exists on disk.
// For symbol anchors, it verifies that the containing file exists.
func VerifyAnchor(anchor string, workspaceRoot string) bool {
	filePortion := cleanAnchorFile(anchor)
	if filePortion == "" {
		return false
	}

	var targetPath string
	if filepath.IsAbs(filePortion) {
		targetPath = filePortion
	} else if workspaceRoot != "" {
		targetPath = filepath.Join(workspaceRoot, filePortion)
	} else {
		targetPath = filePortion
	}

	_, err := os.Stat(targetPath)
	return err == nil
}

// VerifyAnchors partitions a list of anchors into verified and suspect sets.
func VerifyAnchors(anchors []string, workspaceRoot string) (valid []string, suspect []string) {
	valid = make([]string, 0)
	suspect = make([]string, 0)
	for _, a := range anchors {
		if VerifyAnchor(a, workspaceRoot) {
			valid = append(valid, a)
		} else {
			suspect = append(suspect, a)
		}
	}
	return valid, suspect
}

package delivery

import (
	"path/filepath"
	"sort"
	"strings"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/dossiers"
)

// RankedEntry pairs a dossier entry with its composite ranking score and anchor match level.
type RankedEntry struct {
	Entry       dossiers.Entry
	Score       int    // composite ranking score
	AnchorMatch string // "exact", "directory", "scope", or ""
}

// cleanAnchorRaw removes the "file:" prefix and normalizes path separators.
func cleanAnchorRaw(anchor string) string {
	trimmed := strings.TrimSpace(anchor)
	trimmed = strings.TrimPrefix(trimmed, "file:")
	clean := filepath.ToSlash(filepath.Clean(trimmed))
	clean = strings.TrimPrefix(clean, "./")
	if clean == "." || clean == "/" || clean == "" {
		return ""
	}
	return clean
}

// cleanAnchorDir extracts the directory component of an anchor path.
func cleanAnchorDir(anchor string) string {
	file := cleanAnchorFile(anchor)
	if file == "" {
		return ""
	}
	if filepath.Ext(file) != "" {
		dir := filepath.ToSlash(filepath.Dir(file))
		if dir == "." || dir == "/" {
			return ""
		}
		return dir
	}
	return file
}

// matchAnchor evaluates anchor matching between entry anchors and target anchors.
func matchAnchor(entryAnchors []string, targetAnchors []string) (string, int) {
	if len(entryAnchors) == 0 {
		return "scope", 100
	}
	if len(targetAnchors) == 0 {
		return "", 0
	}

	// 1. Check exact file or symbol match (+1000)
	for _, ea := range entryAnchors {
		cleanEA := cleanAnchorFile(ea)
		rawEA := cleanAnchorRaw(ea)
		for _, ta := range targetAnchors {
			cleanTA := cleanAnchorFile(ta)
			rawTA := cleanAnchorRaw(ta)

			// Exact full anchor match
			if rawEA != "" && rawEA == rawTA {
				return "exact", 1000
			}
			// Exact file portion match
			if cleanEA != "" && cleanEA == cleanTA {
				return "exact", 1000
			}
		}
	}

	// 2. Check directory match (+500)
	for _, ea := range entryAnchors {
		dirEA := cleanAnchorDir(ea)
		fileEA := cleanAnchorFile(ea)
		for _, ta := range targetAnchors {
			dirTA := cleanAnchorDir(ta)
			fileTA := cleanAnchorFile(ta)

			if dirEA != "" && dirEA == dirTA {
				return "directory", 500
			}
			if fileTA != "" && (strings.HasPrefix(fileEA, fileTA+"/") || strings.HasPrefix(fileTA, fileEA+"/")) {
				return "directory", 500
			}
			if dirEA != "" && dirTA != "" && (strings.HasPrefix(dirEA, dirTA+"/") || strings.HasPrefix(dirTA, dirEA+"/")) {
				return "directory", 500
			}
		}
	}

	return "", 0
}

func typeScore(t dossiers.EntryType) int {
	switch t {
	case dossiers.EntryTypeInvariant:
		return 80
	case dossiers.EntryTypeFailureSignature:
		return 60
	case dossiers.EntryTypeRuledOut:
		return 50
	case dossiers.EntryTypeGotcha:
		return 40
	case dossiers.EntryTypeDecision:
		return 30
	case dossiers.EntryTypeProcedure:
		return 20
	case dossiers.EntryTypeInterface:
		return 10
	case dossiers.EntryTypeOpenIssue:
		return 5
	default:
		return 0
	}
}

func verifiedScore(verified string) int {
	if verified != "" {
		return 200
	}
	return 0
}

func evidenceScore(evidence []string) int {
	score := len(evidence) * 10
	if score > 50 {
		return 50
	}
	return score
}

// ComputeRankingScore calculates the composite score and anchor match level for an entry.
func ComputeRankingScore(entry dossiers.Entry, targetAnchors []string) (int, string) {
	match, aScore := matchAnchor(entry.Anchors, targetAnchors)
	tScore := typeScore(entry.Type)
	vScore := verifiedScore(entry.Verified)
	eScore := evidenceScore(entry.Evidence)
	return aScore + tScore + vScore + eScore, match
}

// RankEntries scores entries against target anchors and sorts them descending by score.
func RankEntries(entries []dossiers.Entry, targetAnchors []string) []RankedEntry {
	ranked := make([]RankedEntry, len(entries))
	for i, e := range entries {
		score, match := ComputeRankingScore(e, targetAnchors)
		ranked[i] = RankedEntry{
			Entry:       e,
			Score:       score,
			AnchorMatch: match,
		}
	}

	sort.SliceStable(ranked, func(i, j int) bool {
		if ranked[i].Score != ranked[j].Score {
			return ranked[i].Score > ranked[j].Score
		}
		return ranked[i].Entry.ID < ranked[j].Entry.ID
	})

	return ranked
}

// SelectWithinBudget greedily selects ranked entries until the token budget is exhausted.
// Tokens are estimated conservatively as len(entry.Text) / 4.
func SelectWithinBudget(ranked []RankedEntry, tokenBudget int) []RankedEntry {
	if tokenBudget <= 0 {
		return nil
	}

	var selected []RankedEntry
	used := 0
	for _, r := range ranked {
		tokens := len(r.Entry.Text) / 4
		if tokens <= 0 && len(r.Entry.Text) > 0 {
			tokens = 1
		}
		if used+tokens <= tokenBudget {
			selected = append(selected, r)
			used += tokens
		}
	}
	return selected
}

package delivery

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"strings"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/dossiers"
)

// FormatEntry formats a single entry for context injection with its tag marker.
func FormatEntry(entry dossiers.Entry) string {
	return fmt.Sprintf("[repo-memory %s] %s: %s", entry.ID, entry.Type, entry.Text)
}

// FormatEntries formats multiple ranked entries with the standard context header and footer.
func FormatEntries(entries []RankedEntry) string {
	if len(entries) == 0 {
		return ""
	}
	lines := make([]string, 0, len(entries)+2)
	lines = append(lines, "--- repo-memory context ---")
	for _, r := range entries {
		lines = append(lines, FormatEntry(r.Entry))
	}
	lines = append(lines, "---")
	return strings.Join(lines, "\n")
}

// FormatGateDeny formats an advisory deny message for PreToolUse gates.
func FormatGateDeny(entry dossiers.Entry) string {
	text := strings.TrimSpace(entry.Text)
	text = strings.TrimSuffix(text, ".")
	return fmt.Sprintf("[REPO-MEMORY %s] %s. Re-issue the edit after checking this.", entry.ID, text)
}

// ContentHash returns the SHA-256 hexadecimal digest of text.
func ContentHash(text string) string {
	h := sha256.Sum256([]byte(text))
	return hex.EncodeToString(h[:])
}

package delivery

import (
	"context"
	"path/filepath"
	"regexp"
	"strings"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/config"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/dossiers"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/index"
)

// Engine is the core delivery engine that coordinates retrieval, ranking,
// budget enforcement, and anchor verification.
type Engine struct {
	index         *index.Index
	projector     *dossiers.Projector
	scopeResolver *config.ScopeResolver
	workspaceRoot string
	budgets       map[Moment]int
	ledger        *Ledger
}

// EngineOption configures optional parameters for an Engine.
type EngineOption func(*Engine)

// WithBudgets sets custom token budgets per moment.
func WithBudgets(budgets map[Moment]int) EngineOption {
	return func(e *Engine) {
		if budgets != nil {
			e.budgets = make(map[Moment]int)
			for k, v := range budgets {
				e.budgets[k] = v
			}
		}
	}
}

// WithScopeResolver sets the scope resolver for mapping paths and terms to scopes.
func WithScopeResolver(sr *config.ScopeResolver) EngineOption {
	return func(e *Engine) {
		e.scopeResolver = sr
	}
}

// WithProjector sets the dossiers projector.
func WithProjector(p *dossiers.Projector) EngineOption {
	return func(e *Engine) {
		e.projector = p
	}
}

// WithLedger attaches an injection ledger to the engine.
func WithLedger(l *Ledger) EngineOption {
	return func(e *Engine) {
		e.ledger = l
	}
}

// NewEngine constructs a new delivery Engine.
func NewEngine(idx *index.Index, workspaceRoot string, opts ...EngineOption) *Engine {
	e := &Engine{
		index:         idx,
		workspaceRoot: workspaceRoot,
		budgets:       DefaultBudgets(),
	}
	for _, opt := range opts {
		opt(e)
	}
	return e
}

// SetLedger updates or sets the attached ledger.
func (e *Engine) SetLedger(l *Ledger) {
	e.ledger = l
}

// Ledger returns the currently attached ledger, if any.
func (e *Engine) Ledger() *Ledger {
	return e.ledger
}

// areAnchorsAllSuspect returns true if an entry has at least one anchor and NONE of its anchors exist on disk.
func (e *Engine) areAnchorsAllSuspect(anchors []string) bool {
	if len(anchors) == 0 {
		return false
	}
	valid, _ := VerifyAnchors(anchors, e.workspaceRoot)
	return len(valid) == 0
}

func hasGateEditTag(entry dossiers.Entry) bool {
	lower := strings.ToLower(entry.Text)
	if strings.Contains(lower, "gate: edit") || strings.Contains(lower, "gate:edit") {
		return true
	}
	for _, ev := range entry.Evidence {
		if strings.Contains(strings.ToLower(ev), "gate: edit") {
			return true
		}
	}
	return false
}

// TaskStartEntries retrieves entries relevant to prompt terms and git diff paths,
// scores them, and truncates within the MomentTaskStart token budget.
func (e *Engine) TaskStartEntries(ctx context.Context, promptTerms []string, diffPaths []string) ([]RankedEntry, error) {
	if e.index == nil {
		return []RankedEntry{}, nil
	}

	entriesMap := make(map[string]dossiers.Entry)

	// 1. Search by prompt terms via FTS5
	for _, term := range promptTerms {
		trimmed := strings.TrimSpace(term)
		if trimmed == "" {
			continue
		}
		results, err := e.index.SearchEntries(ctx, trimmed)
		if err == nil {
			for _, ent := range results {
				entriesMap[ent.ID] = ent
			}
		}
	}
	if len(promptTerms) > 1 {
		combined := strings.Join(promptTerms, " ")
		results, err := e.index.SearchEntries(ctx, combined)
		if err == nil {
			for _, ent := range results {
				entriesMap[ent.ID] = ent
			}
		}
	}

	// 2. Query anchors by diff paths
	for _, path := range diffPaths {
		clean := cleanAnchorRaw(path)
		if clean == "" {
			continue
		}

		ids, err := e.index.LookupByAnchor(ctx, clean)
		if err == nil {
			for _, id := range ids {
				if _, ok := entriesMap[id]; !ok {
					ent, err := e.index.GetEntry(ctx, id)
					if err == nil && ent != nil {
						entriesMap[id] = *ent
					}
				}
			}
		}

		exactIDs, err := e.index.LookupByAnchorExact(ctx, clean)
		if err == nil {
			for _, id := range exactIDs {
				if _, ok := entriesMap[id]; !ok {
					ent, err := e.index.GetEntry(ctx, id)
					if err == nil && ent != nil {
						entriesMap[id] = *ent
					}
				}
			}
		}

		dir := filepath.Dir(clean)
		if dir != "" && dir != "." && dir != "/" {
			dirIDs, err := e.index.LookupByAnchor(ctx, dir)
			if err == nil {
				for _, id := range dirIDs {
					if _, ok := entriesMap[id]; !ok {
						ent, err := e.index.GetEntry(ctx, id)
						if err == nil && ent != nil {
							entriesMap[id] = *ent
						}
					}
				}
			}
		}
	}

	// 3. Resolve scope if ScopeResolver is provided
	if e.scopeResolver != nil && (len(diffPaths) > 0 || len(promptTerms) > 0) {
		scope := e.scopeResolver.ResolveScope(diffPaths, promptTerms)
		if scope != "" {
			scopeEntries, err := e.index.ListEntriesByScope(ctx, scope)
			if err == nil {
				for _, ent := range scopeEntries {
					entriesMap[ent.ID] = ent
				}
			}
		}
	}

	var candidates []dossiers.Entry
	for _, ent := range entriesMap {
		if ent.Retired {
			continue
		}
		if e.areAnchorsAllSuspect(ent.Anchors) {
			continue
		}
		candidates = append(candidates, ent)
	}

	budget := e.budgets[MomentTaskStart]
	ranked := RankEntries(candidates, diffPaths)
	return SelectWithinBudget(ranked, budget), nil
}

// DossierEntries retrieves invariant, failure-signature, and ruled-out entries
// for the first-entry moment into a dossier scope, within the MomentFirstEntry budget.
func (e *Engine) DossierEntries(ctx context.Context, scope string) ([]RankedEntry, error) {
	if e.index == nil {
		return []RankedEntry{}, nil
	}

	resolved, err := e.index.ResolveAlias(ctx, scope)
	if err == nil && resolved != "" {
		scope = resolved
	}

	entries, err := e.index.ListEntriesByScope(ctx, scope)
	if err != nil {
		return nil, err
	}

	var candidates []dossiers.Entry
	for _, ent := range entries {
		if ent.Retired {
			continue
		}
		if ent.Type != dossiers.EntryTypeInvariant &&
			ent.Type != dossiers.EntryTypeFailureSignature &&
			ent.Type != dossiers.EntryTypeRuledOut {
			continue
		}
		if e.areAnchorsAllSuspect(ent.Anchors) {
			continue
		}
		candidates = append(candidates, ent)
	}

	budget := e.budgets[MomentFirstEntry]
	ranked := RankEntries(candidates, nil)
	return SelectWithinBudget(ranked, budget), nil
}

// AnchorEntries retrieves entries anchored to a file or symbol, verifying disk existence first,
// within the MomentFirstTouch budget.
func (e *Engine) AnchorEntries(ctx context.Context, anchor string) ([]RankedEntry, error) {
	if !VerifyAnchor(anchor, e.workspaceRoot) {
		return []RankedEntry{}, nil
	}
	if e.index == nil {
		return []RankedEntry{}, nil
	}

	seen := make(map[string]bool)
	var candidates []dossiers.Entry

	collect := func(ids []string) {
		for _, id := range ids {
			if seen[id] {
				continue
			}
			seen[id] = true
			ent, err := e.index.GetEntry(ctx, id)
			if err != nil || ent == nil {
				continue
			}
			if ent.Retired {
				continue
			}
			if e.areAnchorsAllSuspect(ent.Anchors) {
				continue
			}
			candidates = append(candidates, *ent)
		}
	}

	exactIDs, err := e.index.LookupByAnchorExact(ctx, anchor)
	if err == nil {
		collect(exactIDs)
	}

	ids, err := e.index.LookupByAnchor(ctx, anchor)
	if err == nil {
		collect(ids)
	}

	filePortion := cleanAnchorFile(anchor)
	if filePortion != "" && filePortion != anchor {
		fileIDs, err := e.index.LookupByAnchor(ctx, filePortion)
		if err == nil {
			collect(fileIDs)
		}
		fileExactIDs, err := e.index.LookupByAnchorExact(ctx, filePortion)
		if err == nil {
			collect(fileExactIDs)
		}
	}

	budget := e.budgets[MomentFirstTouch]
	ranked := RankEntries(candidates, []string{anchor})
	return SelectWithinBudget(ranked, budget), nil
}

// ErrorEntries retrieves failure signatures matching command output, within the MomentError budget.
func (e *Engine) ErrorEntries(ctx context.Context, commandPrefix string, output string) ([]RankedEntry, error) {
	if e.index == nil {
		return []RankedEntry{}, nil
	}

	patterns, err := e.index.LookupErrorPatterns(ctx, commandPrefix)
	if err != nil {
		return nil, err
	}

	matchedIDs := make(map[string]bool)
	for _, p := range patterns {
		if p.Pattern == "" {
			continue
		}
		matched := false
		if strings.Contains(output, p.Pattern) {
			matched = true
		} else {
			re, err := regexp.Compile(p.Pattern)
			if err == nil && re.MatchString(output) {
				matched = true
			}
		}
		if matched {
			matchedIDs[p.EntryID] = true
		}
	}

	var candidates []dossiers.Entry
	for id := range matchedIDs {
		ent, err := e.index.GetEntry(ctx, id)
		if err != nil || ent == nil {
			continue
		}
		if ent.Retired {
			continue
		}
		if e.areAnchorsAllSuspect(ent.Anchors) {
			continue
		}
		candidates = append(candidates, *ent)
	}

	budget := e.budgets[MomentError]
	ranked := RankEntries(candidates, nil)
	return SelectWithinBudget(ranked, budget), nil
}

// GateEntries retrieves unacknowledged entries tagged with "gate: edit" anchored to the target file.
func (e *Engine) GateEntries(ctx context.Context, targetFile string) ([]RankedEntry, error) {
	if e.index == nil {
		return []RankedEntry{}, nil
	}

	cleanTarget := cleanAnchorRaw(targetFile)
	seen := make(map[string]bool)
	var candidates []dossiers.Entry

	collect := func(ids []string) {
		for _, id := range ids {
			if seen[id] {
				continue
			}
			seen[id] = true
			ent, err := e.index.GetEntry(ctx, id)
			if err != nil || ent == nil {
				continue
			}
			if ent.Retired {
				continue
			}
			if !hasGateEditTag(*ent) {
				continue
			}
			if e.ledger != nil && e.ledger.IsGateAcknowledged(ent.ID) {
				continue
			}
			if e.areAnchorsAllSuspect(ent.Anchors) {
				continue
			}
			candidates = append(candidates, *ent)
		}
	}

	exactIDs, err := e.index.LookupByAnchorExact(ctx, targetFile)
	if err == nil {
		collect(exactIDs)
	}
	ids, err := e.index.LookupByAnchor(ctx, targetFile)
	if err == nil {
		collect(ids)
	}

	if cleanTarget != "" && cleanTarget != targetFile {
		cExact, err := e.index.LookupByAnchorExact(ctx, cleanTarget)
		if err == nil {
			collect(cExact)
		}
		cIDs, err := e.index.LookupByAnchor(ctx, cleanTarget)
		if err == nil {
			collect(cIDs)
		}
	}

	budget := e.budgets[MomentGate]
	ranked := RankEntries(candidates, []string{targetFile})
	return SelectWithinBudget(ranked, budget), nil
}

