func setupTestIndex(t *testing.T) (*index.Index, func()) {
	t.Helper()
	dbPath := filepath.Join(t.TempDir(), "test.db")
	idx, err := index.NewIndex(dbPath)
	if err != nil {
		t.Fatalf("failed to create test index: %v", err)
	}
	return idx, func() { idx.Close() }
}

func TestLedger_Lifecycle(t *testing.T) {
	convID := "conv-test-123"
	l := delivery.NewLedger(convID)

	if l.ConversationID != convID {
		t.Fatalf("expected ConversationID %s, got %s", convID, l.ConversationID)
	}

	// 1. Record injection
	rec1 := delivery.InjectionRecord{
		EntryID:     "inv-01",
		Channel:     delivery.ChannelSystem,
		Moment:      delivery.MomentTaskStart,
		StepIndex:   2,
		ContentHash: "hash-01",
	}
	l.RecordInjection(rec1)

	if len(l.Injections) != 1 {
		t.Fatalf("expected 1 injection, got %d", len(l.Injections))
	}
	if l.Injections[0].Tag != "[repo-memory inv-01]" {
		t.Errorf("expected tag '[repo-memory inv-01]', got %q", l.Injections[0].Tag)
	}

	expList := l.GetExposureList()
	if len(expList) != 1 {
		t.Fatalf("expected 1 exposure, got %d", len(expList))
	}
	if expList[0].EntryID != "inv-01" || expList[0].Channel != delivery.ChannelSystem || expList[0].Moment != delivery.MomentTaskStart {
		t.Errorf("unexpected exposure record: %+v", expList[0])
	}

	// 2. Record pull
	l.RecordPull("dec-02")
	expList = l.GetExposureList()
	if len(expList) != 2 {
		t.Fatalf("expected 2 exposures, got %d", len(expList))
	}
	if expList[1].EntryID != "dec-02" || expList[1].Channel != delivery.ChannelPull || expList[1].Moment != "" {
		t.Errorf("unexpected pull exposure: %+v", expList[1])
	}

	// 3. Dossier deduplication
	scope := "core/storage"
	if l.HasSeenDossier(scope) {
		t.Errorf("expected HasSeenDossier false initially")
	}
	l.MarkDossierSeen(scope)
	if !l.HasSeenDossier(scope) {
		t.Errorf("expected HasSeenDossier true after marking")
	}

	// 4. Anchor deduplication
	anchor := "internal/core/storage/db.go"
	if l.HasSeenAnchor(anchor) {
		t.Errorf("expected HasSeenAnchor false initially")
	}
	l.MarkAnchorSeen(anchor)
	if !l.HasSeenAnchor(anchor) {
		t.Errorf("expected HasSeenAnchor true after marking")
	}

	// 5. Gate acknowledgement
	gateID := "inv-gate-1"
	if l.IsGateAcknowledged(gateID) {
		t.Errorf("expected IsGateAcknowledged false initially")
	}
	l.AcknowledgeGate(gateID)
	if !l.IsGateAcknowledged(gateID) {
		t.Errorf("expected IsGateAcknowledged true after acknowledging")
	}

	// 6. Step filtering
	l.RecordInjection(delivery.InjectionRecord{
		EntryID:   "inv-05",
		StepIndex: 5,
	})
	l.RecordInjection(delivery.InjectionRecord{
		EntryID:   "inv-10",
		StepIndex: 10,
	})

	after5 := l.FindInjectionAfterStep(5)
	if len(after5) != 2 {
		t.Fatalf("expected 2 injections at or after step 5, got %d", len(after5))
	}
	after15 := l.FindInjectionAfterStep(15)
	if len(after15) != 0 {
		t.Fatalf("expected 0 injections at or after step 15, got %d", len(after15))
	}

	// 7. RearmDedup
	l.RearmDedup()
	if l.HasSeenDossier(scope) {
		t.Errorf("expected SeenDossiers cleared after RearmDedup")
	}
	if l.HasSeenAnchor(anchor) {
		t.Errorf("expected SeenAnchors cleared after RearmDedup")
	}
	// Gate acknowledgement must remain intact
	if !l.IsGateAcknowledged(gateID) {
		t.Errorf("expected gate acknowledgement preserved across RearmDedup")
	}
}

func TestAnchorVerifier(t *testing.T) {
	ws := t.TempDir()

	subDir := filepath.Join(ws, "pkg", "calc")
	if err := os.MkdirAll(subDir, 0755); err != nil {
		t.Fatalf("MkdirAll: %v", err)
	}

	filePath := filepath.Join(subDir, "calc.go")
	if err := os.WriteFile(filePath, []byte("package calc\nfunc Add() {}\n"), 0644); err != nil {
		t.Fatalf("WriteFile: %v", err)
	}

	// 1. File anchor
	if !delivery.VerifyAnchor("pkg/calc/calc.go", ws) {
		t.Errorf("expected pkg/calc/calc.go to be verified")
	}

	// 2. Symbol anchor with colon
	if !delivery.VerifyAnchor("pkg/calc/calc.go:Add", ws) {
		t.Errorf("expected pkg/calc/calc.go:Add to be verified")
	}

	// 3. Symbol anchor with hash and file: prefix
	if !delivery.VerifyAnchor("file:pkg/calc/calc.go#Add", ws) {
		t.Errorf("expected file:pkg/calc/calc.go#Add to be verified")
	}

	// 4. Directory anchor
	if !delivery.VerifyAnchor("pkg/calc", ws) {
		t.Errorf("expected directory pkg/calc to be verified")
	}

	// 5. Non-existent file
	if delivery.VerifyAnchor("pkg/calc/missing.go", ws) {
		t.Errorf("expected pkg/calc/missing.go to fail verification")
	}

	// 6. Non-existent symbol containing file
	if delivery.VerifyAnchor("pkg/calc/missing.go:Add", ws) {
		t.Errorf("expected pkg/calc/missing.go:Add to fail verification")
	}

	// 7. Empty or pure symbol anchor
	if delivery.VerifyAnchor("", ws) {
		t.Errorf("expected empty anchor to fail verification")
	}
	if delivery.VerifyAnchor("symbol:Add", ws) {
		t.Errorf("expected symbol:Add to fail verification")
	}

	// 8. VerifyAnchors partitioning
	anchors := []string{
		"pkg/calc/calc.go",
		"pkg/calc/calc.go:Add",
		"pkg/calc/nonexistent.go",
		"pkg/calc",
	}
	valid, suspect := delivery.VerifyAnchors(anchors, ws)
	if len(valid) != 3 {
		t.Errorf("expected 3 valid anchors, got %d: %v", len(valid), valid)
	}
	if len(suspect) != 1 || suspect[0] != "pkg/calc/nonexistent.go" {
		t.Errorf("expected suspect ['pkg/calc/nonexistent.go'], got %v", suspect)
	}
}

func TestRanker_ScoringAndOrdering(t *testing.T) {
	// Exact-anchor invariant with evidence > directory-match decision without evidence
	e1 := dossiers.Entry{
		ID:       "inv-01",
		Type:     dossiers.EntryTypeInvariant,
		Anchors:  []string{"internal/calc/add.go"},
		Verified: "verified",
		Evidence: []string{"ep-1:10", "ep-1:12"},
		Text:     "Addition must never overflow without checking.",
	}

	e2 := dossiers.Entry{
		ID:       "dec-01",
		Type:     dossiers.EntryTypeDecision,
		Anchors:  []string{"internal/calc/sub.go"},
		Verified: "",
		Evidence: nil,
		Text:     "Use two's complement arithmetic.",
	}

	target := []string{"internal/calc/add.go"}
	ranked := delivery.RankEntries([]dossiers.Entry{e2, e1}, target)

	if len(ranked) != 2 {
		t.Fatalf("expected 2 ranked entries, got %d", len(ranked))
	}
	if ranked[0].Entry.ID != "inv-01" {
		t.Errorf("expected top entry 'inv-01', got %s", ranked[0].Entry.ID)
	}
	if ranked[0].AnchorMatch != "exact" {
		t.Errorf("expected exact anchor match, got %s", ranked[0].AnchorMatch)
	}
	if ranked[1].Entry.ID != "dec-01" {
		t.Errorf("expected second entry 'dec-01', got %s", ranked[1].Entry.ID)
	}
	if ranked[1].AnchorMatch != "directory" {
		t.Errorf("expected directory anchor match, got %s", ranked[1].AnchorMatch)
	}
	if ranked[0].Score <= ranked[1].Score {
		t.Errorf("expected score of inv-01 (%d) > score of dec-01 (%d)", ranked[0].Score, ranked[1].Score)
	}

	// Scope-only scoring (+100)
	eScope := dossiers.Entry{
		ID:      "inv-scope",
		Type:    dossiers.EntryTypeInvariant,
		Anchors: nil,
		Text:    "General invariant.",
	}
	rankedScope := delivery.RankEntries([]dossiers.Entry{eScope}, target)
	if rankedScope[0].AnchorMatch != "scope" {
		t.Errorf("expected scope match for anchorless entry, got %s", rankedScope[0].AnchorMatch)
	}
	// 100 (scope) + 80 (invariant) = 180
	if rankedScope[0].Score != 180 {
		t.Errorf("expected score 180, got %d", rankedScope[0].Score)
	}
}

func TestRanker_SelectWithinBudget(t *testing.T) {
	// Each entry has 400 chars -> len(Text)/4 = 100 tokens
	text100 := strings.Repeat("abcd", 100)

	entries := []delivery.RankedEntry{
		{Entry: dossiers.Entry{ID: "e1", Text: text100}, Score: 300},
		{Entry: dossiers.Entry{ID: "e2", Text: text100}, Score: 200},
		{Entry: dossiers.Entry{ID: "e3", Text: text100}, Score: 100},
	}

	// Budget of 250 tokens should fit e1 (100) and e2 (100) = 200 tokens. e3 (100) exceeds 250.
	selected := delivery.SelectWithinBudget(entries, 250)
	if len(selected) != 2 {
		t.Fatalf("expected 2 selected entries within budget 250, got %d", len(selected))
	}
	if selected[0].Entry.ID != "e1" || selected[1].Entry.ID != "e2" {
		t.Errorf("unexpected selected IDs: %s, %s", selected[0].Entry.ID, selected[1].Entry.ID)
	}

	// Budget of 50 tokens should fit none of 100-token entries
	selected50 := delivery.SelectWithinBudget(entries, 50)
	if len(selected50) != 0 {
		t.Errorf("expected 0 selected entries within budget 50, got %d", len(selected50))
	}

	// Budget of 0 returns nil
	selected0 := delivery.SelectWithinBudget(entries, 0)
	if len(selected0) != 0 {
		t.Errorf("expected 0 selected entries for 0 budget, got %d", len(selected0))
	}
}

func TestFormatter(t *testing.T) {
	entry := dossiers.Entry{
		ID:   "inv-01J12345",
		Type: dossiers.EntryTypeInvariant,
		Text: "Never import harness packages from core.",
	}

	// 1. FormatEntry
	formatted := delivery.FormatEntry(entry)
	expected := "[repo-memory inv-01J12345] invariant: Never import harness packages from core."
	if formatted != expected {
		t.Errorf("FormatEntry got %q, want %q", formatted, expected)
	}

	// 2. FormatEntries
	ranked := []delivery.RankedEntry{
		{Entry: entry},
		{Entry: dossiers.Entry{
			ID:   "fail-01J99999",
			Type: dossiers.EntryTypeFailureSignature,
			Text: "command: go build\npattern: cannot find package",
		}},
	}
	multi := delivery.FormatEntries(ranked)
	if !strings.HasPrefix(multi, "--- repo-memory context ---\n") {
		t.Errorf("FormatEntries missing standard header:\n%s", multi)
	}
	if !strings.HasSuffix(multi, "\n---") {
		t.Errorf("FormatEntries missing standard footer:\n%s", multi)
	}
	if !strings.Contains(multi, "[repo-memory inv-01J12345]") || !strings.Contains(multi, "[repo-memory fail-01J99999]") {
		t.Errorf("FormatEntries missing entry tag markers:\n%s", multi)
	}

	// Empty FormatEntries
	if delivery.FormatEntries(nil) != "" {
		t.Errorf("expected empty string for empty entries")
	}

	// 3. FormatGateDeny
	deny := delivery.FormatGateDeny(entry)
	expectedDeny := "[REPO-MEMORY inv-01J12345] Never import harness packages from core. Re-issue the edit after checking this."
	if deny != expectedDeny {
		t.Errorf("FormatGateDeny got %q, want %q", deny, expectedDeny)
	}

	// 4. ContentHash
	h1 := delivery.ContentHash("identical content")
	h2 := delivery.ContentHash("identical content")
	h3 := delivery.ContentHash("different content")
	if h1 != h2 {
		t.Errorf("ContentHash not deterministic: %s != %s", h1, h2)
	}
	if h1 == h3 {
		t.Errorf("ContentHash collision on different content: %s", h1)
	}
	if len(h1) != 64 {
		t.Errorf("ContentHash expected length 64 hex, got %d", len(h1))
	}
}

func TestEngine_Integration(t *testing.T) {
	idx, cleanup := setupTestIndex(t)
	defer cleanup()

	ctx := context.Background()
	ws := t.TempDir()

	// Create real files in workspace
	dbDir := filepath.Join(ws, "internal", "db")
	if err := os.MkdirAll(dbDir, 0755); err != nil {
		t.Fatalf("MkdirAll: %v", err)
	}
	dbFile := filepath.Join(dbDir, "store.go")
	if err := os.WriteFile(dbFile, []byte("package db\n"), 0644); err != nil {
		t.Fatalf("WriteFile: %v", err)
	}

	// Populate entries in index
	e1 := dossiers.Entry{
		ID:           "inv-wal",
		Type:         dossiers.EntryTypeInvariant,
		DossierScope: "core/storage",
		Text:         "SQLite database WAL mode must always be enabled.",
		Anchors:      []string{"internal/db/store.go"},
		Verified:     "verified",
		Evidence:     []string{"ep-1"},
	}
	e2 := dossiers.Entry{
		ID:           "fail-lock",
		Type:         dossiers.EntryTypeFailureSignature,
		DossierScope: "core/storage",
		Text:         "database is locked on busy write concurrency",
		Anchors:      []string{"internal/db/store.go"},
	}
	e3 := dossiers.Entry{
		ID:           "rul-mem",
		Type:         dossiers.EntryTypeRuledOut,
		DossierScope: "core/storage",
		Text:         "Never use purely in-memory SQLite tables for production ledger state.",
	}
	e4 := dossiers.Entry{
		ID:           "dec-modernc",
		Type:         dossiers.EntryTypeDecision,
		DossierScope: "core/storage",
		Text:         "Use modernc SQLite driver for pure-Go portability.",
	}
	eRetired := dossiers.Entry{
		ID:           "inv-retired",
		Type:         dossiers.EntryTypeInvariant,
		DossierScope: "core/storage",
		Text:         "Legacy invariant that has been retired.",
		Retired:      true,
	}
	eSuspect := dossiers.Entry{
		ID:           "inv-suspect",
		Type:         dossiers.EntryTypeInvariant,
		DossierScope: "core/storage",
		Text:         "Invariant anchored to a non-existent deleted file.",
		Anchors:      []string{"internal/db/deleted.go"},
	}

	allEntries := []dossiers.Entry{e1, e2, e3, e4, eRetired, eSuspect}
	for _, e := range allEntries {
		if err := idx.UpsertEntry(ctx, e); err != nil {
			t.Fatalf("UpsertEntry %s: %v", e.ID, err)
		}
	}

	// Error patterns
	if err := idx.InsertErrorPattern(ctx, "fail-lock", "go test", "database is locked", "core/storage"); err != nil {
		t.Fatalf("InsertErrorPattern: %v", err)
	}

	ledger := delivery.NewLedger("conv-integ")
	engine := delivery.NewEngine(idx, ws, delivery.WithLedger(ledger))

	// 1. TaskStartEntries
	t.Run("TaskStartEntries", func(t *testing.T) {
		res, err := engine.TaskStartEntries(ctx, []string{"SQLite", "WAL"}, []string{"internal/db/store.go"})
		if err != nil {
			t.Fatalf("TaskStartEntries: %v", err)
		}
		if len(res) == 0 {
			t.Fatalf("expected TaskStartEntries to return results, got 0")
		}
		if res[0].Entry.ID != "inv-wal" {
			t.Errorf("expected top entry 'inv-wal', got %s", res[0].Entry.ID)
		}

		// Ensure retired and suspect entries were filtered out
		for _, r := range res {
			if r.Entry.ID == "inv-retired" {
				t.Errorf("expected retired entry to be skipped")
			}
			if r.Entry.ID == "inv-suspect" {
				t.Errorf("expected suspect entry to be skipped")
			}
		}
	})

	// 2. DossierEntries: only invariant, failure-signature, ruled-out
	t.Run("DossierEntries", func(t *testing.T) {
		res, err := engine.DossierEntries(ctx, "core/storage")
		if err != nil {
			t.Fatalf("DossierEntries: %v", err)
		}
		if len(res) == 0 {
			t.Fatalf("expected DossierEntries to return results, got 0")
		}

		allowedTypes := map[dossiers.EntryType]bool{
			dossiers.EntryTypeInvariant:        true,
			dossiers.EntryTypeFailureSignature: true,
			dossiers.EntryTypeRuledOut:         true,
		}

		for _, r := range res {
			if !allowedTypes[r.Entry.Type] {
				t.Errorf("DossierEntries returned disallowed type %s for entry %s", r.Entry.Type, r.Entry.ID)
			}
			if r.Entry.Retired {
				t.Errorf("DossierEntries returned retired entry %s", r.Entry.ID)
			}
			if r.Entry.ID == "inv-suspect" {
				t.Errorf("DossierEntries returned suspect entry %s", r.Entry.ID)
			}
		}
	})

	// 3. AnchorEntries: skips suspect anchors
	t.Run("AnchorEntries", func(t *testing.T) {
		// Existing file anchor
		res, err := engine.AnchorEntries(ctx, "internal/db/store.go")
		if err != nil {
			t.Fatalf("AnchorEntries store.go: %v", err)
		}
		if len(res) == 0 {
			t.Fatalf("expected AnchorEntries to find entries for internal/db/store.go")
		}

		// Suspect file anchor (does not exist on disk)
		resSuspect, err := engine.AnchorEntries(ctx, "internal/db/deleted.go")
		if err != nil {
			t.Fatalf("AnchorEntries deleted.go: %v", err)
		}
		if len(resSuspect) != 0 {
			t.Errorf("expected suspect anchor to return 0 entries, got %d", len(resSuspect))
		}
	})

	// 4. ErrorEntries
	t.Run("ErrorEntries", func(t *testing.T) {
		res, err := engine.ErrorEntries(ctx, "go test ./...", "Error executing transaction: database is locked on busy write concurrency")
		if err != nil {
			t.Fatalf("ErrorEntries: %v", err)
		}
		if len(res) != 1 || res[0].Entry.ID != "fail-lock" {
			t.Fatalf("expected fail-lock, got %+v", res)
		}

		// Non-matching error output
		resNone, err := engine.ErrorEntries(ctx, "go test ./...", "syntax error: unexpected token")
		if err != nil {
			t.Fatalf("ErrorEntries non-matching: %v", err)
		}
		if len(resNone) != 0 {
			t.Errorf("expected 0 entries for non-matching error, got %d", len(resNone))
		}
	})

	// 5. GateEntries
	t.Run("GateEntries", func(t *testing.T) {
		gateEntry := dossiers.Entry{
			ID:           "inv-gate-schema",
			Type:         dossiers.EntryTypeInvariant,
			DossierScope: "core/storage",
			Text:         "gate: edit - Never modify SQL schema without migration script.",
			Anchors:      []string{"internal/db/store.go"},
		}
		if err := idx.UpsertEntry(ctx, gateEntry); err != nil {
			t.Fatalf("UpsertEntry gateEntry: %v", err)
		}

		// Unacknowledged gate
		res, err := engine.GateEntries(ctx, "internal/db/store.go")
		if err != nil {
			t.Fatalf("GateEntries: %v", err)
		}
		if len(res) == 0 {
			t.Fatalf("expected gate entry to be found")
		}
		if res[0].Entry.ID != "inv-gate-schema" {
			t.Errorf("expected gate entry 'inv-gate-schema', got %s", res[0].Entry.ID)
		}

		// Acknowledge gate
		ledger.AcknowledgeGate("inv-gate-schema")

		// Query again: should be empty because gate is acknowledged
		resAck, err := engine.GateEntries(ctx, "internal/db/store.go")
		if err != nil {
			t.Fatalf("GateEntries after ack: %v", err)
		}
		if len(resAck) != 0 {
			t.Errorf("expected 0 gate entries after acknowledgment, got %d", len(resAck))
		}
	})

	// 6. Budget truncation
	t.Run("BudgetTruncation", func(t *testing.T) {
		scope := "core/budget-test"
		longText := strings.Repeat("test", 100) // 400 chars = 100 tokens

		for i := 0; i < 5; i++ {
			entry := dossiers.Entry{
				ID:           dossiers.EntryTypePrefixes[dossiers.EntryTypeInvariant] + string(rune('a'+i)),
				Type:         dossiers.EntryTypeInvariant,
				DossierScope: scope,
				Text:         longText,
			}
			if err := idx.UpsertEntry(ctx, entry); err != nil {
				t.Fatalf("UpsertEntry: %v", err)
			}
		}

		// MomentFirstEntry budget is 150 tokens. With 100-token entries, only 1 should fit!
		res, err := engine.DossierEntries(ctx, scope)
		if err != nil {
			t.Fatalf("DossierEntries budget test: %v", err)
		}
		if len(res) != 1 {
			t.Errorf("expected 1 entry to fit in 150 token budget, got %d", len(res))
		}
	})
}

