func TestEngineOptions(t *testing.T) {
	customBudgets := map[delivery.Moment]int{
		delivery.MomentTaskStart: 800,
	}
	l1 := delivery.NewLedger("conv-1")
	l2 := delivery.NewLedger("conv-2")

	engine := delivery.NewEngine(nil, "",
		delivery.WithBudgets(customBudgets),
		delivery.WithLedger(l1),
		delivery.WithScopeResolver(nil),
		delivery.WithProjector(nil),
	)

	if engine.Ledger() != l1 {
		t.Errorf("expected Ledger() to return l1")
	}
	engine.SetLedger(l2)
	if engine.Ledger() != l2 {
		t.Errorf("expected Ledger() to return l2 after SetLedger")
	}
}

func TestRanker_AllTypesAndEvidenceCap(t *testing.T) {
	types := []struct {
		entryType dossiers.EntryType
		wantScore int
	}{
		{dossiers.EntryTypeInvariant, 80},
		{dossiers.EntryTypeFailureSignature, 60},
		{dossiers.EntryTypeRuledOut, 50},
		{dossiers.EntryTypeGotcha, 40},
		{dossiers.EntryTypeDecision, 30},
		{dossiers.EntryTypeProcedure, 20},
		{dossiers.EntryTypeInterface, 10},
		{dossiers.EntryTypeOpenIssue, 5},
		{dossiers.EntryType("unknown"), 0},
	}

	for _, tc := range types {
		e := dossiers.Entry{
			ID:   "test",
			Type: tc.entryType,
		}
		score, _ := delivery.ComputeRankingScore(e, nil)
		// No target anchors & no anchors -> 100 (scope) + type score
		if score != 100+tc.wantScore {
			t.Errorf("type %s: expected score %d, got %d", tc.entryType, 100+tc.wantScore, score)
		}
	}

	// Test evidence capping at 50
	evidence10 := make([]string, 10)
	for i := range evidence10 {
		evidence10[i] = "ev"
	}
	eCapped := dossiers.Entry{
		ID:       "capped",
		Type:     dossiers.EntryTypeInvariant,
		Evidence: evidence10,
	}
	scoreCapped, _ := delivery.ComputeRankingScore(eCapped, nil)
	// 100 (scope) + 80 (invariant) + 50 (evidence capped at 50) = 230
	if scoreCapped != 230 {
		t.Errorf("expected score 230 for capped evidence, got %d", scoreCapped)
	}
}

